service.method:

SELECT DISTINCT CAST(GWLN.APP_LINE_SEQ AS DECIMAL) AS `DEC`
     , GWLN.APP_METHOD
     , GWLN.APP_USER_ID
  FROM SGWLN GWLN
 WHERE GWLN.HOUSE_CODE = ${session.HOUSE_CODE}
   AND GWLN.COMPANY_CODE = ${session.COMPANY_CODE}
   AND GWLN.APP_NO= ${APP_NO}
   AND GWLN.APP_NO_SEQ = ${APP_NO_SEQ}
   AND GWLN.APP_LINE_STATUS != 'L01'
   AND GWLN.APP_TYPE != 'L06'
   AND GWLN.APP_METHOD IN ('01','04')
 ORDER BY CAST(GWLN.APP_LINE_SEQ AS DECIMAL)


UPDATE SGWGL
   SET SUX_WKEY4 = ${IAMS_DOC_NO}
 WHERE HOUSE_CODE 	= ${session.HOUSE_CODE} 
   AND COMPANY_CODE 	= ${session.COMPANY_CODE}
   AND APP_NO = ${APP_NO}
   AND APP_NO_SEQ = ${APP_NO_SEQ}
